#!/usr/bin/env python3
"""Generate KPP declarations and reactions for region-by-sector methane."""

from pathlib import Path


REGIONS = (
    "USA", "CAN", "MEX", "CAC", "BRA", "NSA", "SCN", "WEU", "EEU",
    "RUS", "MDE", "NAF", "WAF", "CAF", "EAF", "SIO", "SAC", "CAS",
    "IND", "SAS", "CHN", "EAS", "SEA", "OCE", "ROW",
)
SECTORS = (
    "OIL", "GAS", "COL", "LIV", "LDF", "WST", "RIC", "OTA", "BBN",
    "WTL", "SEE", "LAK", "TER", "RES",
)


def declarations() -> str:
    lines = [
        "// This file is generated by util/generate_region_sector_kpp.py.",
        "// Do not edit it manually.",
    ]
    for region in REGIONS:
        for sector in SECTORS:
            tracer = f"CH4_{region}_{sector}"
            lines.extend((
                f"{tracer:<17} = IGNORE;  {{ Methane from {region} {sector} emissions }}",
                f"L{tracer}byOH    = IGNORE;  {{ Tracks loss of {tracer} by OH }}",
                f"L{tracer}byCl    = IGNORE;  {{ Tracks loss of {tracer} by Cl }}",
                f"L{tracer}byO1D   = IGNORE;  {{ Tracks loss of {tracer} by O1D }}",
                f"L{tracer}bySoil  = IGNORE;  {{ Tracks loss of {tracer} by Soil }}",
            ))
    return "\n".join(lines) + "\n"


def reactions() -> str:
    lines = [
        "// This file is generated by util/generate_region_sector_kpp.py.",
        "// Do not edit it manually.",
    ]
    for region in REGIONS:
        for sector in SECTORS:
            tracer = f"CH4_{region}_{sector}"
            lines.extend((
                f"{tracer} + FixedOH  = DummyCO + L{tracer}byOH   : 2.45d-12*EXP(-1775.0d0/TEMP);",
                f"{tracer} + FixedCl  = DummyCO + L{tracer}byCl   : 9.60d-12*EXP(-1360.0d0/TEMP);",
                f"{tracer} + FixedO1D = DummyCO + L{tracer}byO1D  : 1.75d-10;",
                f"{tracer:<17} = DummyCO + L{tracer}bySoil : k_Oxidants(4);",
            ))
    return "\n".join(lines) + "\n"


def replace_generated_block(
    text: str, begin: str, end: str, generated: str
) -> str:
    prefix, remainder = text.split(begin, maxsplit=1)
    _, suffix = remainder.split(end, maxsplit=1)
    return f"{prefix}{begin}\n{generated}{end}{suffix}"


def main() -> None:
    directory = Path(__file__).resolve().parent.parent
    mechanism = directory / "oxidants.eqn"
    text = mechanism.read_text()
    text = replace_generated_block(
        text,
        "// BEGIN GENERATED REGION-BY-SECTOR SPECIES",
        "// END GENERATED REGION-BY-SECTOR SPECIES",
        declarations(),
    )
    text = replace_generated_block(
        text,
        "// BEGIN GENERATED REGION-BY-SECTOR REACTIONS",
        "// END GENERATED REGION-BY-SECTOR REACTIONS",
        reactions(),
    )
    mechanism.write_text(text)


if __name__ == "__main__":
    main()
